const https = require('https');
const http = require('http');
const url = require('url');

// Function to make HTTP/HTTPS requests
function makeRequest(urlString, options = {}) {
  return new Promise((resolve, reject) => {
    const parsedUrl = new URL(urlString);
    const reqOptions = {
      hostname: parsedUrl.hostname,
      port: parsedUrl.port,
      path: parsedUrl.pathname + parsedUrl.search,
      method: 'GET',
      timeout: 10000, // 10 second timeout
      ...options
    };

    // Choose the appropriate module based on protocol
    const reqModule = parsedUrl.protocol === 'https:' ? https : http;

    const req = reqModule.request(reqOptions, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        resolve({
          statusCode: res.statusCode,
          statusMessage: res.statusMessage,
          headers: res.headers,
          body: data,
          url: urlString
        });
      });
    });

    req.on('error', (error) => {
      reject({
        error: error.message,
        url: urlString
      });
    });

    req.on('timeout', () => {
      req.destroy();
      reject({
        error: 'Request timeout',
        url: urlString
      });
    });

    req.end();
  });
}

// Test endpoints
async function testEndpoints() {
  const endpoints = [
    'http://localhost:47301/checkConnectivity?variant=2',
    'https://httpstat.us/200'
  ];

  console.log('Testing endpoints...\n');

  for (const endpoint of endpoints) {
    try {
      console.log(`Testing: ${endpoint}`);
      const startTime = Date.now();

      const response = await makeRequest(endpoint);
      const endTime = Date.now();
      const responseTime = endTime - startTime;

      console.log(`✓ Status: ${response.statusCode} ${response.statusMessage}`);
      console.log(`✓ Response Time: ${responseTime}ms`);
      console.log(`✓ Headers: ${JSON.stringify(response.headers, null, 2)}`);
      console.log(`✓ Body Preview: ${response.body.substring(0, 200)}${response.body.length > 200 ? '...' : ''}`);

      // Analyze response for warnings
      if (response.statusCode !== 200) {
        console.warn(`⚠️  Warning: Non-200 status code: ${response.statusCode}`);
      }

      if (responseTime > 5000) {
        console.warn(`⚠️  Warning: Slow response time: ${responseTime}ms`);
      }

      // Check for error messages in body
      const lowerBody = response.body.toLowerCase();
      const errorIndicators = ['error', 'fail', 'warn', 'exception', 'denied', 'unauthorized', 'forbidden'];
      const foundErrors = errorIndicators.filter(indicator => lowerBody.includes(indicator));

      if (foundErrors.length > 0) {
        console.warn(`⚠️  Warning: Found potential error indicators in response: ${foundErrors.join(', ')}`);
      }

      console.log('---\n');
    } catch (error) {
      console.error(`✗ Failed to connect to ${endpoint}`);
      console.error(`  Error: ${error.error || error.message || JSON.stringify(error)}`);
      console.log('---\n');
    }
  }
}

// Run tests
testEndpoints().catch(console.error);

